INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خمط:khalil_kitab_ayn', 'خمط', '9a9f29603aaf38c9912dd9ddce', 'الخَمْطُ: ضرب من الأراك يؤكل', 'a kind of arāk tree that is eaten', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_7ab7349cd798165c', '1335', NULL, 'blk_kay_bfd84b0bf2f802cc', 0, NULL, 'Marker: head gloss. Reading: arāk tree. Primary: a kind of tree (arāk) — 6 of 9 books (al-Khalīl blk_kay_bfd84b0bf2f802cc; Ibn Durayd blk_jam_249b3b4df3cef8ae; al-Jawharī blk_sih_3007c756b51a4a41; al-Rāghib blk_mfr_03d39519b7cd33e8; Lisān blk_lsn_48c94ad0dcfe9bfd; Lane blk_lane_6684591133c85c36). Other readings: roasting skinned meat: al-Qāmūs, Tāj · smooth and bare: Ibn Fāris · attacking, domineering: Ibn Fāris.', 'high', 'active');
