INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خمط:ibn_manzur_lisan_arab', 'خمط', '9a9f29603aaf38c9912dd9ddce', 'قَالَ اللَّيْثُ: الخَمْطُ ضَرْبٌ مِنَ الأَراكِ لَهُ حَمْل يؤْكل', 'a kind of arāk with edible fruit', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_9f3cfc30cbca9ba6', '3679', 7, 'blk_lsn_48c94ad0dcfe9bfd', 0, NULL, 'Marker: first definition after headword. Reading: arāk tree. Quoted from al-Layth via Lisān.', 'high', 'active');
