INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خوض:zabidi_taj_arus', 'خوض', '1307b3126070193c47a45f8619', 'خَوْضاً وخِيَاضاً، بالكَسْرِ: دَحَلَهُ ومَشَى فِيهِ', 'went into the water and walked in it', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_f7cd960fa43ad76b', '322', 18, 'blk_taj_84faeb148181b615', 0, NULL, 'Marker: Qāmūs gloss + addition. Reading: wading.', 'high', 'active');
