INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خون:raghib_mufradat', 'خون', 'fc2080b09c358216559ac46ec7', 'فالخيانة: مخالفة الحقّ بنقض العهد في السّرّ', 'going against right by secretly breaking a pledge', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_9a8ad839b76357d9', '305', 1, 'blk_mfr_e0740d4cf5cbf026', 0, NULL, 'Marker: opening definition. Reading: betrayal. Primary: breaking trust — 6 of 9 books (Ibn Durayd blk_jam_771067225d091cef; al-Jawharī blk_sih_ef46d743660e7ce2; al-Rāghib blk_mfr_e0740d4cf5cbf026; Lisān blk_lsn_4106a246fcec974a; al-Miṣbāḥ blk_msb_f343e4eb7db08060; al-Qāmūs blk_qms_9b18cfb91d3331fe). Other readings: lessening, loss: Ibn Fāris, Tāj, Lane.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خون:ibn_manzur_lisan_arab', 'خون', 'fc2080b09c358216559ac46ec7', 'الخَوْنُ أَن يُؤْتَمن الإِنسانُ فَلَا يَنْصَحَ', 'being trusted and not staying true', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_62e428ec950172c0', '6705', 13, 'blk_lsn_4106a246fcec974a', 0, NULL, 'Marker: first definition after headword. Reading: breaking trust. Quoted from Ibn Sīdah via Lisān.', 'high', 'active');
