INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:درج:jawhari_sihah', 'درج', '9b7a8c3b173e9a4bffa875c606', 'دَرَجَ الرجل والضَبُّ يَدْرُجُ دُروجاً وَدَرَجاناً، أي مشى. ودَرَجَ، أي مضى لسبيله', 'he walked; he went his way', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_6f9571079456be01', '616', 1, 'blk_sih_af8f214d16d05a66', 0, NULL, 'Marker: head gloss. Reading: walking on. Primary: walking on, passing — 6 of 10 books (al-Jawharī blk_sih_af8f214d16d05a66; Ibn Fāris blk_mqy_bde48bc19bd5c423; al-Miṣbāḥ blk_msb_31b5faead25abff8; al-Qāmūs blk_qms_137db9915376f767; Tāj blk_taj_b947985324e7aeb3; Lane blk_lane_a6d5abc4a662b729). Other readings: steps, rank: al-Khalīl, Ibn Durayd, al-Rāghib, Lisān.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:درج:raghib_mufradat', 'درج', '9b7a8c3b173e9a4bffa875c606', 'الدّرجة نحو المنزلة، لكن يقال للمنزلة: درجة إذا اعتبرت بالصّعود دون الامتداد على البسيطة', 'a rank seen as going up, like a step', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_75945282b85d8eff', '310', 1, 'blk_mfr_2021251fd3a8ae74', 0, NULL, 'Marker: head gloss. Reading: steps, rank. Differs from the main reading (walking on, passing).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:درج:ibn_manzur_lisan_arab', 'درج', '9b7a8c3b173e9a4bffa875c606', 'دَرَجُ البناءِ ودُرَّجُه، بِالتَّثْقِيلِ: مَراتِبُ بَعْضُهَا فَوْقَ بَعْضٍ', 'a building''s steps, one above another', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_d444cfbb841db8ef', '1070', 2, 'blk_lsn_445c2971f08c15f4', 0, NULL, 'Marker: head gloss. Reading: steps, rank. Differs from the main reading (walking on, passing).', 'high', 'active');
