INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:درس:khalil_kitab_ayn', 'درس', '0df08eb40ac033b6a400748672', 'الدَّرْسُ: ضَرْبٌ من الجَرَب يبقَى له أَثَرٌ مُتَفَشٍّ في الجِلْد', 'a mange that leaves a spreading mark', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_150ce6b579637e9c', '2531', NULL, 'blk_kay_d7b60cadcc4e65e5', 0, NULL, 'Marker: head gloss. Reading: mange mark. Also gives: wearing away, fading (blk_kay_3b689c03b74c3578).', 'medium', 'active');
