INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:درس:raghib_mufradat', 'درس', '0df08eb40ac033b6a400748672', 'دَرَسَ الدّار معناه: بقي أثرها، وبقاء الأثر يقتضي انمحاءه في نفسه', 'only its trace stays; the thing itself is gone', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_66981a48d556c497', '311', 1, 'blk_mfr_fbace80127f749d4', 0, NULL, 'Marker: «معناه». Reading: faded trace.', 'high', 'active');
