INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:درس:fayyumi_misbah_munir', 'درس', '0df08eb40ac033b6a400748672', 'دَرَسَ الْمَنْزِلُ دُرُوسًا مِنْ بَابِ قَعَدَ عَفَا وَخَفِيَتْ آثَارُهُ', 'the home wore away; its traces were hidden', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_10615617e5d84e9f', '954', NULL, 'blk_msb_f1437e6f315028d6', 0, NULL, 'Marker: head gloss. Reading: wearing away.', 'high', 'active');
