INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:دعو:jawhari_sihah', 'دعو', '088602bf5a869628360b217426', 'ودعوت فلانا، أي صِحْتُ به واسْتَدْعَيْتُهُ', 'I called out to him and summoned him', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_d7b88caafd5bf606', '4632', 6, 'blk_sih_681648eb24f6d4ac', 0, NULL, 'Marker: «أي». Reading: calling. Primary: calling someone to you — 5 of 7 books (al-Jawharī blk_sih_681648eb24f6d4ac; Ibn Fāris blk_mqy_80c30686f89c6d53; al-Rāghib blk_mfr_7e67b1c8e6ecce7d; Lisān blk_lsn_e0d54ebe9e13f9f9; al-Miṣbāḥ blk_msb_0bcd3f8d0cdc6ab3). Other readings: praying to God: al-Miṣbāḥ, Tāj · asking, seeking: Lane.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:دعو:raghib_mufradat', 'دعو', '088602bf5a869628360b217426', 'الدُّعَاء كالنّدا', 'calling, like calling out', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_c97fc1c99d65d1ae', '315', 1, 'blk_mfr_7e67b1c8e6ecce7d', 0, NULL, 'Marker: head gloss. Reading: calling.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:دعو:ibn_manzur_lisan_arab', 'دعو', '088602bf5a869628360b217426', 'ودَعا الرجلَ دَعْواً ودُعَاءً: نَادَاهُ، وَالِاسْمُ الدَّعْوَة', 'he called out to the man', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_80d49aa14163bb7b', '3933', 8, 'blk_lsn_e0d54ebe9e13f9f9', 0, NULL, 'Marker: head gloss (after Qurʾān opening). Reading: calling.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:دعو:fayyumi_misbah_munir', 'دعو', '088602bf5a869628360b217426', 'دَعَوْتُ اللَّهَ أَدْعُوهُ دُعَاءً ابْتَهَلْتُ إلَيْهِ بِالسُّؤَالِ', 'I prayed to God, pleading and asking', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_8127f08cf8f8b832', '971', NULL, 'blk_msb_0bcd3f8d0cdc6ab3', 0, NULL, 'Marker: head gloss. Reading: praying. Also gives: calling someone to you (blk_msb_0bcd3f8d0cdc6ab3).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:دعو:zabidi_taj_arus', 'دعو', '088602bf5a869628360b217426', 'الدُّعاءُ) ، بالضَّمِّ مَمْدوداً؛ (الرَّغْبَةُ إِلَى اللَّهِ تَعَالَى)', 'turning to God with longing; prayer', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_436d179e628838e8', '46', 38, 'blk_taj_74b2cb25f9ecf1fd', 0, NULL, 'Marker: Qāmūs gloss. Reading: praying. Differs from the main reading (calling someone to you).', 'high', 'active');
